namespace ShipmentTracker.Client.Models;

public enum ShipmentStatus
{
    Pending,
    InTransit,
    OutForDelivery,
    Delivered,
    Delayed
}

public class Shipment
{
    public int Id { get; set; }
    public string TrackingNumber { get; set; } = string.Empty;
    public string Origin { get; set; } = string.Empty;
    public string Destination { get; set; } = string.Empty;
    public ShipmentStatus Status { get; set; }
    public DateTime? EstimatedDelivery { get; set; }
    public string CustomerEmail { get; set; } = string.Empty;
    public string Description { get; set; } = string.Empty;
    public DateTime CreatedAt { get; set; }
}

using ShipmentTracker.Client.Models;

namespace ShipmentTracker.Client.Services;

public interface IShipmentService
{
    Task<List<Shipment>> GetAllShipmentsAsync();
    Task<Shipment?> GetShipmentByTrackingNumberAsync(string trackingNumber);
    Task<Shipment> CreateShipmentAsync(Shipment shipment);
    Task UpdateShipmentStatusAsync(int id, ShipmentStatus status);
}

using System.Net.Http.Json;
using ShipmentTracker.Client.Models;

namespace ShipmentTracker.Client.Services;

public class ClientShipmentService(HttpClient http) : IShipmentService
{
    public async Task<List<Shipment>> GetAllShipmentsAsync()
    {
        return await http.GetFromJsonAsync<List<Shipment>>("api/shipments") ?? [];
    }

    public async Task<Shipment?> GetShipmentByTrackingNumberAsync(string trackingNumber)
    {
        var response = await http.GetAsync($"api/shipments/track/{trackingNumber}");
        if (!response.IsSuccessStatusCode)
            return null;
        return await response.Content.ReadFromJsonAsync<Shipment>();
    }

    public async Task<Shipment> CreateShipmentAsync(Shipment shipment)
    {
        var response = await http.PostAsJsonAsync("api/shipments", shipment);
        response.EnsureSuccessStatusCode();
        return (await response.Content.ReadFromJsonAsync<Shipment>())!;
    }

    public async Task UpdateShipmentStatusAsync(int id, ShipmentStatus status)
    {
        var response = await http.PutAsJsonAsync($"api/shipments/{id}/status", status);
        response.EnsureSuccessStatusCode();
    }
}

using ShipmentTracker.Client.Models;
using ShipmentTracker.Client.Services;

namespace ShipmentTracker.Services;

public class ServerShipmentService : IShipmentService
{
    private static readonly List<Shipment> _shipments = new()
    {
        new Shipment { Id = 1, TrackingNumber = "SHP-001-2026", Origin = "New York, US", Destination = "London, UK", Status = ShipmentStatus.InTransit, EstimatedDelivery = DateTime.UtcNow.AddDays(3), CustomerEmail = "alice@example.com", Description = "Electronics - 2 boxes", CreatedAt = DateTime.UtcNow.AddDays(-2) },
        new Shipment { Id = 2, TrackingNumber = "SHP-002-2026", Origin = "Shanghai, CN", Destination = "Los Angeles, US", Status = ShipmentStatus.Pending, EstimatedDelivery = DateTime.UtcNow.AddDays(12), CustomerEmail = "bob@example.com", Description = "Furniture - 1 pallet", CreatedAt = DateTime.UtcNow.AddDays(-1) },
        new Shipment { Id = 3, TrackingNumber = "SHP-003-2026", Origin = "Berlin, DE", Destination = "Tokyo, JP", Status = ShipmentStatus.OutForDelivery, EstimatedDelivery = DateTime.UtcNow.AddDays(1), CustomerEmail = "carol@example.com", Description = "Auto parts - 5 boxes", CreatedAt = DateTime.UtcNow.AddDays(-5) },
        new Shipment { Id = 4, TrackingNumber = "SHP-004-2026", Origin = "Sydney, AU", Destination = "Mumbai, IN", Status = ShipmentStatus.Delivered, EstimatedDelivery = DateTime.UtcNow.AddDays(-1), CustomerEmail = "dave@example.com", Description = "Textiles - 3 cartons", CreatedAt = DateTime.UtcNow.AddDays(-7) },
        new Shipment { Id = 5, TrackingNumber = "SHP-005-2026", Origin = "São Paulo, BR", Destination = "Paris, FR", Status = ShipmentStatus.Delayed, EstimatedDelivery = DateTime.UtcNow.AddDays(5), CustomerEmail = "eve@example.com", Description = "Food products - refrigerated", CreatedAt = DateTime.UtcNow.AddDays(-3) },
    };

    private static int _nextId = 6;
    private static readonly Lock _lock = new();

    public Task<List<Shipment>> GetAllShipmentsAsync()
    {
        lock (_lock)
        {
            return Task.FromResult(_shipments.ToList());
        }
    }

    public Task<Shipment?> GetShipmentByTrackingNumberAsync(string trackingNumber)
    {
        lock (_lock)
        {
            var shipment = _shipments.FirstOrDefault(s =>
                s.TrackingNumber.Equals(trackingNumber, StringComparison.OrdinalIgnoreCase));
            return Task.FromResult(shipment);
        }
    }

    public Task<Shipment> CreateShipmentAsync(Shipment shipment)
    {
        lock (_lock)
        {
            shipment.Id = _nextId++;
            shipment.CreatedAt = DateTime.UtcNow;
            _shipments.Add(shipment);
            return Task.FromResult(shipment);
        }
    }

    public Task UpdateShipmentStatusAsync(int id, ShipmentStatus status)
    {
        lock (_lock)
        {
            var shipment = _shipments.FirstOrDefault(s => s.Id == id);
            if (shipment is not null)
            {
                shipment.Status = status;
            }
            return Task.CompletedTask;
        }
    }
}

