        {
            <div class="card shadow-sm">
                <div class="card-header d-flex justify-content-between align-items-center">
                    <strong>@shipment.TrackingNumber</strong>
                    <span class="badge @GetStatusBadgeClass(shipment.Status) fs-6">@shipment.Status</span>
                </div>
                <div class="card-body">
                    <dl class="row mb-0">
                        <dt class="col-sm-5">Origin</dt>
                        <dd class="col-sm-7">@shipment.Origin</dd>

                        <dt class="col-sm-5">Destination</dt>
                        <dd class="col-sm-7">@shipment.Destination</dd>

                        <dt class="col-sm-5">Description</dt>
                        <dd class="col-sm-7">@shipment.Description</dd>

                        <dt class="col-sm-5">Estimated Delivery</dt>
                        <dd class="col-sm-7">
                            @if (shipment.EstimatedDelivery.HasValue)
                            {
                                <strong>@shipment.EstimatedDelivery.Value.ToString("dddd, MMMM dd, yyyy")</strong>
                                @{
                                    var daysLeft = (shipment.EstimatedDelivery.Value - DateTime.UtcNow).Days;
                                }
                                @if (daysLeft > 0)
                                {
                                    <span class="text-muted"> (@daysLeft days remaining)</span>
                                }
                                else if (daysLeft == 0)
                                {
                                    <span class="text-success"> (arriving today)</span>
                                }
                            }
                            else
                            {
                                <span class="text-muted">Not yet determined</span>
                            }
                        </dd>

