@using ShipmentTracker.Client.Models
@using ShipmentTracker.Client.Services
@attribute [Authorize]
@inject IShipmentService ShipmentService

<PageTitle>Track Shipment</PageTitle>

<h1>Track Your Shipment</h1>

<div class="row justify-content-center mt-4">
    <div class="col-md-6">
        <div class="input-group mb-3">
            <input class="form-control form-control-lg" placeholder="Enter tracking number (e.g., SHP-001-2026)"
                   @bind="trackingNumber" @onkeydown="HandleKeyDown" />
            <button class="btn btn-primary btn-lg" @onclick="TrackShipment" disabled="@isLoading">
                @if (isLoading)
                {
                    <span class="spinner-border spinner-border-sm" role="status"></span>
                }
                else
                {
                    <span>Track</span>
                }
            </button>
        </div>

        @if (searched && shipment is null)
        {
            <div class="alert alert-warning">
                <strong>Not found.</strong> No shipment matches tracking number "@searchedNumber".
            </div>
        }

        @if (shipment is not null)
        {
            <div class="card shadow-sm">
                <div class="card-header d-flex justify-content-between align-items-center">
                    <strong>@shipment.TrackingNumber</strong>
                    <span class="badge @GetStatusBadgeClass(shipment.Status) fs-6">@shipment.Status</span>
                </div>
